/**
 * Utility for resolving optimized WebP avatar and master pose thumbnails
 * generated by scripts/generate-avatar-thumbnails.ts in public/avatars/thumbs/.
 */

/**
 * Resolves an avatar or master pose path to its optimized WebP thumbnail URL.
 * 
 * Examples:
 *   "/avatars/ruby.png" -> "/avatars/thumbs/ruby.webp"
 *   "/avatars/mateo.jpg" -> "/avatars/thumbs/mateo.webp"
 *   "/avatars/master_ruby_archive/domain_chroma_wall_standing_burgundy_velvet_corset/01.jpg"
 *     -> "/avatars/thumbs/master_ruby_archive/domain_chroma_wall_standing_burgundy_velvet_corset/01.webp"
 */
export function getAvatarThumbnailUrl(url?: string | null): string {
  if (!url) {
    return "/avatars/thumbs/ruby.webp";
  }

  // Already a thumbnail
  if (url.includes("/avatars/thumbs/")) {
    return url;
  }

  // Root avatar or master archive pose
  if (url.startsWith("/avatars/")) {
    const relative = url.slice("/avatars/".length);

    // Skip video files (e.g. mp4 preview loops)
    if (relative.endsWith(".mp4") || relative.endsWith(".webm") || relative.endsWith(".mov")) {
      return url;
    }

    const withoutExt = relative.replace(/\.(png|jpe?g|webp)$/i, "");
    return `/avatars/thumbs/${withoutExt}.webp`;
  }

  return url;
}

/**
 * Image onError fallback handler to smoothly recover if a thumbnail is missing
 */
export function handleAvatarImgError(
  event: React.SyntheticEvent<HTMLImageElement, Event>,
  fallbackSrc: string = "/avatars/ruby.png"
): void {
  const target = event.currentTarget;
  if (target.src !== fallbackSrc && !target.src.endsWith(fallbackSrc)) {
    target.src = fallbackSrc;
  }
}
